{
 "summary": "The file states four NP-hardness results under deterministic polynomial-time Karp reductions from every NP language (TM2 polytime model, bit-string encodings): (1) GapCVP in ℓ2 with gap n^{1/400}, for nonsingular integer bases and integer targets; (2) binary nearest codeword with gap n^{1/200}; (3) binary syndrome decoding with gap n^{1/200}; (4) GapCVP in ℓp for each rational p ≥ 1 with gap n^{1/(200p)}. Items (1)–(3) match Theorem 1 and Corollary 15 of the excerpt. The most important caveat is that the ℓp statement (4) and its gap exponent are not in the excerpt, and it drops the integer-target requirement, so it cannot be checked against the paper. The `disjoint` fields are sorry'd but appear true.",
 "glossary": [
  {"decl": "GapCVP.IsNP", "line": 49, "plain": "L ∈ NP: there exist a polynomial bound and a polytime TM2 verifier V such that L(x) ⇔ ∃ certificate c with |c| ≤ bound(|x|) and V(x,c) = true.", "standard_concept": "NP (verifier definition)", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.PromiseReduction", "line": 140, "plain": "A polytime map f with x ∈ L ⇒ f(x) ∈ YES and x ∉ L ⇒ f(x) ∈ NO.", "standard_concept": "Karp reduction to a promise problem", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.IsNPHardPromise", "line": 147, "plain": "Every NP language Karp-reduces to the promise problem.", "standard_concept": "NP-hardness of a promise problem", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.encodeInstance", "line": 74, "plain": "Self-delimiting (length-prefixed) concatenation of dimension, radius, target and basis rows.", "standard_concept": "binary encoding of a CVP instance", "matches_standard": "yes", "note": "Injective because the dimension comes first and every field is length-prefixed."},
  {"decl": "GapCVP.Comparator.wellFormed", "line": 80, "plain": "det B ≠ 0 and r > 0. The conjunct 0 ≤ n is vacuous; n = 0 is allowed since the det of the empty matrix is 1.", "standard_concept": "nonsingular basis, positive radius", "matches_standard": "yes", "note": "n = 0 instances are degenerate but harmless."},
  {"decl": "GapCVP.Comparator.distanceSquared", "line": 91, "plain": "‖Bv − t‖₂²", "standard_concept": "squared Euclidean distance to the lattice point Bv", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.gapCVP400Promise", "line": 135, "plain": "YES: an encoded instance with integer t, well-formed, and dist₂(t, L(B)) ≤ r. NO: an encoded instance with integer t, well-formed, and every v satisfies dist > n^{1/400}·r.", "standard_concept": "GapCVP_{n^{1/400}}", "matches_standard": "yes", "note": "Comparing squares is equivalent to comparing distances since r > 0."},
  {"decl": "GapCVP.Comparator.binaryNearestCodewordPromise", "line": 187, "plain": "YES: n > 0, R > 0, and ∃ c with wt(u − Gc) ≤ R. NO: n > 0, R > 0, and ∀ c, wt(u − Gc) > n^{1/200}·R.", "standard_concept": "Gap nearest codeword over F₂", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.binarySyndromeDecodingPromise", "line": 244, "plain": "YES: ∃ x with Hx = b and wt(x) ≤ R. NO: the system Hx = b is consistent, and every solution x has wt(x) > n^{1/200}·R.", "standard_concept": "Gap syndrome decoding over F₂", "matches_standard": "yes", "note": "NO additionally requires consistency, matching the proof sketch."},
  {"decl": "GapCVP.Comparator.finitePGapCVPPromise", "line": 287, "plain": "ℓp GapCVP with gap n^{1/(200p)}, rational p ≥ 1, rational target allowed.", "standard_concept": "GapCVP in ℓp", "matches_standard": "unclear", "note": "The ℓp statement is not in the excerpt."}
 ],
 "lean_claims": [
  {"theorem": "gapCVP400IsNPHard", "line": 153, "plain": "Every NP language Karp-reduces in polytime to GapCVP_{n^{1/400}} (ℓ2, integer target, nonsingular integer basis)."},
  {"theorem": "binaryNearestCodewordIsNPHard", "line": 212, "plain": "Every NP language reduces to binary nearest codeword with gap n^{1/200}."},
  {"theorem": "binarySyndromeDecodingIsNPHard", "line": 268, "plain": "Every NP language reduces to binary syndrome decoding with gap n^{1/200}."},
  {"theorem": "finitePNormGapCVPIsNPHard", "line": 307, "plain": "For each rational p ≥ 1, every NP language reduces to ℓp GapCVP with gap n^{1/(200p)}."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1", "plain": "GapCVP_{n^{1/400}} is NP-hard under deterministic polytime many-one reductions (nonsingular B ∈ Z^{n×n}, t ∈ Z^n, r ∈ Q_{>0})."},
  {"ref": "Corollary 15", "plain": "Binary nearest codeword and binary syndrome decoding are NP-hard to approximate within n^{1/200}."},
  {"ref": "Section 7 fixed-finite-norm consequence", "plain": "Not in excerpt."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1", "lean_theorem": "gapCVP400IsNPHard", "relation": "equivalent", "why": "Reduction from all NP languages via 3SAT is equivalent; YES/NO conditions match."},
  {"paper_ref": "Corollary 15", "lean_theorem": "binaryNearestCodewordIsNPHard", "relation": "equivalent", "why": "Definitions match."},
  {"paper_ref": "Corollary 15", "lean_theorem": "binarySyndromeDecodingIsNPHard", "relation": "equivalent", "why": "NO requires consistency, consistent with the proof's setup."},
  {"paper_ref": "Section 7 fixed-finite-norm consequence", "lean_theorem": "finitePNormGapCVPIsNPHard", "relation": "different", "why": "Statement not in excerpt; cannot verify the exponent 1/(200p) or the target type."}
 ],
 "flags": [
  {"id": "F1", "category": "coverage", "severity": "medium", "decl": "finitePGapCVPPromise", "line": 287, "paper_ref": null, "explanation": "The ℓp result (gap n^{1/(200p)}, p rational ≥ 1) is not in the excerpt, so the exponent and the range of p cannot be checked. Unlike gapCVP400, this promise omits hasIntegerTarget, so the YES/NO sets admit rational targets. Larger target sets make a reduction easier, so this is slightly weaker than an integer-target version.", "polarity": "lean weaker", "probe_idea": "Compare with the paper's ℓp corollary; optionally add hasIntegerTarget to the YES and NO conditions."},
  {"id": "F2", "category": "other", "severity": "low", "decl": "gapCVP400Promise", "line": 138, "plain": null, "explanation": "The disjointness fields of all four promises are `sorry`. If one were false, the promise would be ill-formed. They appear true: encodings are injective, the gap factor is ≥ 1 when n ≥ 1, and the n = 0 cases give 0^x = 0, which makes NO false.", "polarity": "n/a", "probe_idea": "Prove each disjoint field, e.g. ∀ bits, yesLanguage bits → noLanguage bits → False, using injectivity of encodeInstance."},
  {"id": "F3", "category": "other", "severity": "low", "decl": "wellFormed", "line": 82, "paper_ref": "Theorem 1", "explanation": "Dimension 0 is allowed (det of the empty matrix = 1), and the conjunct 0 ≤ dimension is vacuous. Such instances can only be YES, so this is harmless.", "polarity": "n/a", "probe_idea": null},
  {"id": "F4", "category": "other", "severity": "low", "decl": "binarySyndromeDecodingPromise", "line": 259, "paper_ref": "Corollary 15", "explanation": "NO requires Hx = b to be solvable. This shrinks the NO set, making the Lean statement slightly stronger, and it matches the paper's proof setup.", "polarity": "lean stronger", "probe_idea": null}
 ],
